import{_ as e,o as i,c as a,ah as t}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"cocotb and the Celox CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cocotb.md","filePath":"guide/cocotb.md"}'),n={name:"guide/cocotb.md"};function l(o,s,p,d,h,r){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="cocotb-and-the-celox-cli" tabindex="-1">cocotb and the Celox CLI <a class="header-anchor" href="#cocotb-and-the-celox-cli" aria-label="Permalink to &quot;cocotb and the Celox CLI&quot;">​</a></h1><p>Celox can compile a Veryl or SystemVerilog design into a native executable that runs ordinary <a href="https://www.cocotb.org/" target="_blank" rel="noreferrer">cocotb</a> tests through VPI. The generated executable contains the compiled design and the Celox runtime; it does not need the HDL sources when it runs.</p><h2 id="build-the-cli" tabindex="-1">Build the CLI <a class="header-anchor" href="#build-the-cli" aria-label="Permalink to &quot;Build the CLI&quot;">​</a></h2><p>The CLI is currently built from the Celox source tree:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox-vpi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemverilog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox</span></span></code></pre></div><p>The <code>run</code> command below needs no Python installation. For VPI tests, install cocotb into the Python environment you want to use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cocotb</span></span></code></pre></div><p>The repository dev container already includes cocotb 2.0.1 and Verilator.</p><h2 id="run-an-hdl-testbench-directly" tabindex="-1">Run an HDL testbench directly <a class="header-anchor" href="#run-an-hdl-testbench-directly" aria-label="Permalink to &quot;Run an HDL testbench directly&quot;">​</a></h2><p>Use the same command for a SystemVerilog testbench and a Veryl native <code>#[test]</code> module:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/types.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Dut.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/Top.sv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span></span></code></pre></div><p>For SystemVerilog, pass <code>.sv</code> or <code>.v</code> sources in compilation order. The command uses four-state simulation and runs until <code>$finish</code> or no scheduled events remain. For Veryl, pass one project entry file: Celox discovers <code>Veryl.toml</code> and collects the project&#39;s sources and dependencies. A standalone Veryl file also works. Select the native testbench module with <code>--top</code>. Veryl uses the existing native testbench executor; a test may also complete by falling through its initial blocks.</p><p>The command uses the existing frontends&#39; supported language subsets; unsupported constructs produce compilation diagnostics. <code>-O O0</code>, <code>-O O1</code>, and <code>-O O2</code> select the existing compiler optimization levels. Both languages default to O2, including dead store elimination; signals read by the HDL testbench are retained automatically. An explicit <code>-O</code> overrides the default.</p><p>Successful completion returns status 0. Compilation errors, runtime errors, assertion failures, <code>$error</code>, <code>$fatal</code>, lost runtime events, and exhausted execution limits return status 1. SV <code>$stop</code> also returns status 1 because this command has no interactive debugger. Invalid command arguments return status 2. SV <code>$display</code>/<code>$write</code> output goes to stdout; the existing Veryl native testbench executor sends its HDL output to stderr.</p><p><code>--max-steps N</code> sets a positive execution limit (default: 1000000). It counts scheduler steps for SV and testbench ticks for Veryl. Reaching the Veryl tick limit before completion fails the command. This limit does not bound compilation or work within a single step/tick; use an external process timeout when a wall clock limit is needed. Source languages cannot be mixed in one invocation.</p><h2 id="manage-a-multi-file-project" tabindex="-1">Manage a multi-file project <a class="header-anchor" href="#manage-a-multi-file-project" aria-label="Permalink to &quot;Manage a multi-file project&quot;">​</a></h2><p>Save common inputs and named targets in <code>celox.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sources = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rtl/pkg.sv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filelists = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rtl/design.f&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">include_dirs = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_target = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;smoke&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defines</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SIMULATION = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diagnostics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mixed_timescale = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warn&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smoke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sources = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test/Tb.sv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">top = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tb&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opt_level = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;O1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_steps = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">top = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Dut&quot;</span></span></code></pre></div><p>Both commands resolve the same sources, include directories, macros and top:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/dut-sim</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/celox.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span></span></code></pre></div><p>With no explicit sources or <code>-f</code> arguments, or when <code>--target</code> is present, Celox searches the current directory and its parents for <code>celox.toml</code>. Explicit <code>--project FILE</code> selects a manifest directly. Relative manifest paths resolve from the manifest&#39;s directory, including paths in its targets. Positional sources and <code>-f</code> alone run independently of any nearby manifest.</p><p>Targets inherit the root settings. Sources are collected in this order: root <code>sources</code>, root <code>filelists</code>, target <code>sources</code>, target <code>filelists</code>, then CLI sources and <code>-f</code> expansions in command-line order. Each list retains its source order. Include directories accumulate in the same layer order. Macro definitions are global to the invocation; later definitions win, with CLI <code>-D</code> definitions applied last. TOML macro values are strings. Configured macros apply to each source; macros defined in HDL files retain the frontend&#39;s per-file compilation-unit scope. <code>--top</code> overrides the selected top; <code>run</code>&#39;s <code>-O</code> and <code>--max-steps</code> override the target/root run settings. VPI builds retain the existing force-compatible compilation settings.</p><p>Without <code>--target</code>, Celox uses <code>default_target</code>, otherwise the root <code>top</code>, otherwise the sole target. Multiple targets without a default require <code>--target</code>. A project may also name a single <code>.veryl</code> entry file; its Veryl project discovery still uses <code>Veryl.toml</code>.</p><p>Compilation diagnostic levels can be set in <code>[diagnostics]</code>, overridden in <code>[targets.NAME.diagnostics]</code>, and overridden again with repeatable <code>--diagnostic CODE=allow|warn|error</code> options on either command. See <a href="./celox-toml.html#diagnostics">diagnostic configuration</a> for supported recovery behavior and examples.</p><h3 id="use-a-file-list-directly" tabindex="-1">Use a file list directly <a class="header-anchor" href="#use-a-file-list-directly" aria-label="Permalink to &quot;Use a file list directly&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/all.f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rtl/design.f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Dut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/dut-sim</span></span></code></pre></div><p>A <code>.f</code> file contains whitespace-separated source paths and can contain nested lists and preprocessing options:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Paths resolve from this file&#39;s directory.</span></span>
<span class="line"><span>../rtl/pkg.sv</span></span>
<span class="line"><span>-f ../rtl/design.f</span></span>
<span class="line"><span>+incdir+../include</span></span>
<span class="line"><span>+define+SIMULATION=1</span></span>
<span class="line"><span>&quot;../test/with spaces/Tb.sv&quot;</span></span></code></pre></div><p>Supported options are <code>-f FILE</code>, <code>-I DIR</code>/<code>-IDIR</code>, <code>-D NAME[=VALUE]</code>/<code>-DNAME[=VALUE]</code>, <code>+incdir+DIR[+DIR...]</code> and <code>+define+NAME[=VALUE][+NAME[=VALUE]...]</code>. Bare macro names expand to <code>1</code>. Paths may be quoted or use backslash escapes; <code>#</code> and <code>//</code> start comments at a token boundary, and <code>/* ... */</code> comments are also accepted. Every nested list resolves paths from its own directory. The file-list reader performs no environment, wildcard or shell expansion. Unknown options, unknown TOML fields and cyclic file lists are errors. The CLI accepts <code>-I</code>/<code>--include-dir</code> and <code>-D</code>/<code>--define</code> directly as well. Include directories and macros require SystemVerilog inputs and a build with <code>--features systemverilog</code>.</p><h2 id="compile-a-design" tabindex="-1">Compile a design <a class="header-anchor" href="#compile-a-design" aria-label="Permalink to &quot;Compile a design&quot;">​</a></h2><p>Pass one source in the Veryl project and name the top-level module:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>Celox finds <code>Veryl.toml</code> from the source path and includes the project&#39;s source files and dependencies. For a standalone source outside a Veryl project, it compiles that file alone. The output defaults to <code>celox.out</code> when <code>-o</code> is omitted.</p><p>For SystemVerilog, pass one or more <code>.sv</code> files in compilation order:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/types.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Child.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.sv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>This compiles the specified files using Celox&#39;s supported SystemVerilog subset. List package definitions before their consumers. It does not discover a <code>Veryl.toml</code> project or additional SystemVerilog source files. Multiple inputs must all be <code>.sv</code> files; for Veryl, pass one project entry file. The <code>celox-vpi-compile</code> binary accepts the same source list.</p><h2 id="run-cocotb" tabindex="-1">Run cocotb <a class="header-anchor" href="#run-cocotb" aria-label="Permalink to &quot;Run cocotb&quot;">​</a></h2><p>Suppose <code>test/test_top.py</code> contains a cocotb test. Run the generated executable from a directory where that module is importable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span></span></code></pre></div><p>The executable automatically:</p><ul><li>uses <code>python3</code> and locates its cocotb VPI adapter and libpython;</li><li>supplies the compiled top-level name to cocotb;</li><li>writes <code>results.xml</code> and returns a failing exit status when a test fails.</li></ul><p>Use another Python environment or result path explicitly when needed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --results-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/results.xml</span></span></code></pre></div><p><code>--test-filter REGEX</code> selects matching tests; <code>--testcase NAME</code> is also available for cocotb&#39;s legacy test selection. <code>--vpi PATH</code> overrides automatic VPI adapter discovery. The corresponding cocotb environment variables remain supported for existing automation: <code>PYGPI_PYTHON_BIN</code>, <code>LIBPYTHON_LOC</code>, <code>CELOX_COCOTB_VPI</code>, <code>COCOTB_TEST_MODULES</code>, <code>COCOTB_TEST_FILTER</code>, and <code>COCOTB_RESULTS_FILE</code>.</p><h2 id="current-compatibility" tabindex="-1">Current compatibility <a class="header-anchor" href="#current-compatibility" aria-label="Permalink to &quot;Current compatibility&quot;">​</a></h2><p>The compatibility layer covers cocotb 2.0 paths for module and signal discovery, immediate/deposit/force/release writes, scalar and vector values, simulation time, and the Start, ReadWrite, ReadOnly, NextTimeStep, Timer, ValueChange, and End callback regions.</p><p>Packed bit handles, delayed VPI writes, unpacked-array indexing, and derived/cascaded clock scheduling are not yet supported.</p>`,47)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
